$target = Join-Path $PSScriptRoot '..\src\screens\DownloadedLibraryScreen.tsx'
$source = @'
import {useEffect,useMemo,useState} from 'react';
import {ActivityIndicator,Alert,Pressable,ScrollView,StyleSheet,Text,View} from 'react-native';
import {SafeAreaView} from 'react-native-safe-area-context';
import {useAudioPlayer,useAudioPlayerStatus} from 'expo-audio';
import {listOfflineJuz,listOfflineSurahs,localAyahAudioUri,readOfflineSurah,removeAllOfflineJuz,removeSurahOffline} from '../services/offlineQuran';
import {formatDownloadSize,listDownloads,OFFLINE_SECTIONS,removeDownload,type OfflineSection} from '../services/offlineDownloads';
import {ayahTranslation,ayahTransliteration,type QuranSurah} from '../services/quran';

type Item={id:string;section:OfflineSection;title:string;subtitle:string;kind?:'surah'|'juz';number?:number;reciterId?:string;language?:string;size?:number;date?:string;remove:()=>Promise<void>};
const G='#087A45',INK='#173B2D';
const sectionNames:Record<OfflineSection,string>={quran:'Quran',tafsir:'Tafsir',hadith:'Hadith',duas:'Duas',books:'Books',lifestyle:'Islamic Lifestyle',prophets:'Prophets',sahaba:'Sahaba','islamic-history':'Islamic History'};

function OfflineSurahReader({item,onClose}:{item:Item;onClose:()=>void}){
 const[surah,setSurah]=useState<QuranSurah|null>(null),[loading,setLoading]=useState(true),[audioAyah,setAudioAyah]=useState<number|null>(null);
 const player=useAudioPlayer(null,{updateInterval:500});const status=useAudioPlayerStatus(player);
 useEffect(()=>{let live=true;setLoading(true);readOfflineSurah(item.number!,item.language||'en','').then(value=>{if(live)setSurah(value)}).finally(()=>live&&setLoading(false));return()=>{live=false;player.pause()}},[item.id,item.language,item.number,player]);
 const listen=async(index:number)=>{if(!surah||!item.reciterId)return;if(audioAyah===index&&status.playing){player.pause();return}const ayah=surah.ayahs[index];const uri=await localAyahAudioUri(surah.number,item.reciterId,ayah.number);if(!uri){Alert.alert('Audio unavailable','The offline audio file could not be found.');return}player.replace({uri,name:`${surah.englishName} - Ayah ${ayah.numberInSurah}`});setAudioAyah(index);player.play()};
 useEffect(()=>{if(status.didJustFinish&&surah&&audioAyah!==null&&audioAyah<surah.ayahs.length-1)void listen(audioAyah+1)},[status.didJustFinish]);
 return <View style={s.reader}><View style={s.readerHead}><Pressable onPress={onClose} style={s.readerBack}><Text style={s.readerBackText}>{'‹'} Downloads</Text></Pressable><View style={s.readerBadge}><Text style={s.readerBadgeText}>OFFLINE</Text></View></View>{loading?<ActivityIndicator color={G} style={{marginVertical:60}}/>:!surah?<View style={s.empty}><Text style={s.emptyTitle}>Offline text unavailable</Text></View>:<><View style={s.readerHero}><Text style={s.readerArabic}>{surah.name}</Text><Text style={s.readerTitle}>{surah.englishName}</Text><Text style={s.readerSub}>{surah.englishNameTranslation} · {surah.numberOfAyahs} Ayahs</Text></View>{surah.ayahs.map((ayah,index)=><View key={ayah.number} style={s.ayahCard}><View style={s.ayahTop}><View style={s.ayahNumber}><Text style={s.ayahNumberText}>{ayah.numberInSurah}</Text></View><Pressable onPress={()=>void listen(index)} style={[s.ayahListen,audioAyah===index&&status.playing&&s.ayahListenOn]}><Text style={[s.ayahListenText,audioAyah===index&&status.playing&&s.ayahListenTextOn]}>{audioAyah===index&&status.playing?'Pause':'Listen'}</Text></Pressable></View><Text style={s.ayahArabic}>{ayah.text}</Text>{ayahTransliteration(ayah,item.language||'en')?<Text style={s.pronunciation}>{ayahTransliteration(ayah,item.language||'en')}</Text>:null}<Text style={s.translation}>{ayahTranslation(ayah,item.language||'en')}</Text></View>)}</>}</View>
}

export function DownloadedLibraryScreen({language,onBack,onOpenQuran,onReadJuz}:{language:string;onBack:()=>void;onOpenQuran:()=>void;onReadSurah:(number:number)=>void;onListenSurah:(number:number)=>void;onReadJuz:(number:number)=>void}){
 const[items,setItems]=useState<Item[]>([]),[active,setActive]=useState<OfflineSection|null>(null),[loading,setLoading]=useState(true),[readerItem,setReaderItem]=useState<Item|null>(null);
 const load=async()=>{setLoading(true);try{const[surahs,juz,packages]=await Promise.all([listOfflineSurahs(),listOfflineJuz(),listDownloads()]);const rows:Item[]=[...surahs.map(row=>({id:`surah-${row.key}`,section:'quran' as const,title:`Surah ${row.surahNumber}`,subtitle:`${row.ayahCount} Ayahs · ${row.language.toUpperCase()} · Audio included`,kind:'surah' as const,number:row.surahNumber,reciterId:row.reciterId,language:row.language,date:row.downloadedAt,remove:()=>removeSurahOffline(row.surahNumber,row.reciterId)})),...juz.map(number=>({id:`juz-${number}`,section:'quran' as const,title:`Juz ${number}`,subtitle:'Quran text and recitation',kind:'juz' as const,number,remove:()=>removeAllOfflineJuz(number)})),...packages.map(row=>({id:row.id,section:row.section,title:row.title,subtitle:`${row.items} saved items · ${row.language.toUpperCase()}`,language:row.language,size:row.bytes,date:row.downloadedAt,remove:()=>removeDownload(row.id)}))];setItems(rows)}finally{setLoading(false)}};
 useEffect(()=>{void load()},[language]);
 const shown=active?items.filter(item=>item.section===active):[];const total=items.reduce((sum,item)=>sum+(item.size||0),0);
 const remove=(item:Item)=>Alert.alert('Remove download?',`${item.title} will be deleted from this device.`,[{text:'Cancel',style:'cancel'},{text:'Remove',style:'destructive',onPress:()=>void item.remove().then(load)}]);
 return <SafeAreaView style={s.safe}><View style={s.header}><Pressable onPress={readerItem?()=>setReaderItem(null):onBack} hitSlop={12}><Text style={s.back}>‹</Text></Pressable><View><Text style={s.title}>{readerItem?readerItem.title:'Downloads'}</Text><Text style={s.sub}>{readerItem?'Reading from this device':`${items.length} saved item${items.length===1?'':'s'} on this device`}</Text></View><View style={s.storage}><Text style={s.storageText}>{readerItem?'OFFLINE':formatDownloadSize(total)}</Text></View></View><ScrollView contentContainerStyle={s.content} showsVerticalScrollIndicator={false}>{readerItem?<OfflineSurahReader item={readerItem} onClose={()=>setReaderItem(null)}/>:<><View style={s.hero}><Text style={s.heroTitle}>Your offline library</Text><Text style={s.heroText}>Read downloaded content and listen to saved audio without leaving this page.</Text></View>{active===null?<View style={s.categoryGrid}>{OFFLINE_SECTIONS.map(section=>{const count=items.filter(item=>item.section===section.id).length;return <Pressable key={section.id} onPress={()=>setActive(section.id)} style={s.categoryCard}><View style={s.categoryIcon}><Text style={s.categoryLetter}>{section.title.slice(0,1)}</Text></View><View style={s.categoryCopy}><Text numberOfLines={1} style={s.categoryTitle}>{section.title}</Text><Text style={s.categoryCount}>{count} downloaded</Text></View><Text style={s.categoryArrow}>›</Text></Pressable>})}</View>:<><View style={s.listHead}><Pressable onPress={()=>setActive(null)} style={s.categoriesBack}><Text style={s.categoriesBackText}>‹ Categories</Text></Pressable><View><Text style={s.listTitle}>{sectionNames[active]}</Text><Text style={s.listCount}>{shown.length} saved item{shown.length===1?'':'s'}</Text></View></View>{loading?<ActivityIndicator color={G}/>:shown.length?<View style={s.grid}>{shown.map(item=><View key={item.id} style={s.card}><View style={s.cardTop}><View style={s.icon}><Text style={s.iconText}>{sectionNames[item.section].slice(0,1)}</Text></View><View style={s.category}><Text style={s.categoryText}>{sectionNames[item.section]}</Text></View></View><View style={s.cardBody}><Text numberOfLines={2} style={s.cardTitle}>{item.title}</Text><Text numberOfLines={3} style={s.cardSub}>{item.subtitle}</Text>{item.size?<Text style={s.meta}>{formatDownloadSize(item.size)}</Text>:null}{item.date?<Text style={s.date}>{new Date(item.date).toLocaleDateString()}</Text>:null}</View><View style={s.actions}>{item.kind==='surah'?<><Pressable onPress={()=>setReaderItem(item)} style={s.open}><Text style={s.openText}>Read</Text></Pressable><Pressable onPress={()=>setReaderItem(item)} style={s.listen}><Text style={s.listenText}>Listen</Text></Pressable></>:item.kind==='juz'&&item.number?<Pressable onPress={()=>onReadJuz(item.number!)} style={s.open}><Text style={s.openText}>Read</Text></Pressable>:<Pressable onPress={onOpenQuran} style={s.open}><Text style={s.openText}>Open</Text></Pressable>}<Pressable onPress={()=>remove(item)} style={s.remove}><Text style={s.removeText}>Remove</Text></Pressable></View></View>)}</View>:<View style={s.empty}><View style={s.emptyIcon}><Text style={s.emptyArrow}>↓</Text></View><Text style={s.emptyTitle}>No downloads yet</Text><Text style={s.emptyText}>Use the Download button beside any content. It will appear here under its section.</Text></View>}</>}</>}</></ScrollView></SafeAreaView>
}

const s=StyleSheet.create({safe:{flex:1,backgroundColor:'#F8FCF8'},header:{height:76,paddingHorizontal:18,borderBottomWidth:1,borderBottomColor:'#E1EBE4',backgroundColor:'#FFF',flexDirection:'row',alignItems:'center',gap:13},back:{fontSize:32,color:G},title:{fontSize:21,fontWeight:'800',color:INK},sub:{fontSize:10,color:'#718078'},storage:{marginLeft:'auto',paddingHorizontal:10,paddingVertical:7,borderRadius:12,backgroundColor:'#E9F6ED'},storageText:{fontSize:9,fontWeight:'800',color:G},content:{padding:16,paddingBottom:50},hero:{padding:16,borderRadius:19,backgroundColor:'#0B704B'},heroTitle:{fontSize:17,fontWeight:'800',color:'#FFF'},heroText:{marginTop:5,fontSize:10.5,lineHeight:16,color:'#D9F2E3'},categoryGrid:{paddingVertical:14,flexDirection:'row',flexWrap:'wrap',justifyContent:'space-between',rowGap:9},categoryCard:{width:'48.5%',minHeight:192,padding:18,borderRadius:20,borderWidth:1,borderColor:'#D7E7DC',backgroundColor:'#FFF',elevation:2},categoryIcon:{width:64,height:64,borderRadius:20,backgroundColor:'#E9F6ED',alignItems:'center',justifyContent:'center'},categoryLetter:{fontSize:22,fontWeight:'900',color:G},categoryCopy:{width:'100%',marginTop:14},categoryTitle:{fontSize:18,fontWeight:'800',color:INK},categoryCount:{marginTop:7,fontSize:11.5,color:'#7A887F'},categoryArrow:{position:'absolute',right:18,bottom:16,fontSize:30,color:G},listHead:{marginTop:14,marginBottom:12,flexDirection:'row',alignItems:'center',justifyContent:'space-between'},categoriesBack:{height:38,paddingHorizontal:12,borderRadius:12,backgroundColor:'#E8F5EC',justifyContent:'center'},categoriesBackText:{fontSize:10,fontWeight:'800',color:G},listTitle:{fontSize:18,fontWeight:'800',color:INK},listCount:{fontSize:9.5,color:'#718078'},grid:{gap:11},card:{width:'100%',minHeight:174,padding:15,borderRadius:20,borderWidth:1,borderColor:'#D9E7DD',backgroundColor:'#FFF',shadowColor:'#174832',shadowOffset:{width:0,height:3},shadowOpacity:.07,shadowRadius:8,elevation:2},cardTop:{flexDirection:'row',alignItems:'center',justifyContent:'space-between'},icon:{width:43,height:43,borderRadius:14,backgroundColor:'#E8F5EC',alignItems:'center',justifyContent:'center'},iconText:{fontSize:16,fontWeight:'900',color:G},category:{paddingHorizontal:8,paddingVertical:5,borderRadius:9,backgroundColor:'#FFF5D9'},categoryText:{fontSize:8,fontWeight:'800',color:'#98701C'},cardBody:{marginTop:8},cardTitle:{fontSize:16,fontWeight:'800',color:INK},cardSub:{marginTop:4,fontSize:10,lineHeight:15,color:'#718078'},meta:{marginTop:5,fontSize:9,fontWeight:'800',color:G},date:{marginTop:4,fontSize:8.5,color:'#8A968F'},actions:{marginTop:13,flexDirection:'row',gap:7},open:{flex:1,height:39,borderRadius:11,backgroundColor:G,alignItems:'center',justifyContent:'center'},openText:{fontSize:10.5,fontWeight:'800',color:'#FFF'},listen:{flex:1,height:39,borderRadius:11,backgroundColor:'#E8F5EC',alignItems:'center',justifyContent:'center'},listenText:{fontSize:10.5,fontWeight:'800',color:G},remove:{flex:1,height:39,borderRadius:11,backgroundColor:'#FFF0ED',alignItems:'center',justifyContent:'center'},removeText:{fontSize:9.5,fontWeight:'800',color:'#B34A42'},empty:{marginTop:32,alignItems:'center',paddingHorizontal:30},emptyIcon:{width:64,height:64,borderRadius:22,backgroundColor:'#E8F5EC',alignItems:'center',justifyContent:'center'},emptyArrow:{fontSize:30,color:G},emptyTitle:{marginTop:15,fontSize:19,fontWeight:'800',color:INK},emptyText:{marginTop:7,fontSize:11,lineHeight:17,textAlign:'center',color:'#718078'},reader:{paddingBottom:20},readerHead:{flexDirection:'row',alignItems:'center',justifyContent:'space-between',marginBottom:12},readerBack:{paddingHorizontal:12,paddingVertical:9,borderRadius:12,backgroundColor:'#E8F5EC'},readerBackText:{fontSize:11,fontWeight:'800',color:G},readerBadge:{paddingHorizontal:10,paddingVertical:6,borderRadius:10,backgroundColor:'#FFF2C8'},readerBadgeText:{fontSize:8,fontWeight:'900',color:'#9A7319'},readerHero:{padding:20,borderRadius:22,backgroundColor:'#0B704B',alignItems:'center',marginBottom:12},readerArabic:{fontSize:27,lineHeight:43,color:'#FFF',textAlign:'center'},readerTitle:{marginTop:6,fontSize:20,fontWeight:'900',color:'#FFF'},readerSub:{marginTop:4,fontSize:10,color:'#D8EFE2'},ayahCard:{marginBottom:11,padding:17,borderRadius:20,borderWidth:1,borderColor:'#D9E7DD',backgroundColor:'#FFF'},ayahTop:{flexDirection:'row',justifyContent:'space-between',alignItems:'center'},ayahNumber:{width:36,height:36,borderRadius:12,backgroundColor:'#E8F5EC',alignItems:'center',justifyContent:'center'},ayahNumberText:{fontSize:12,fontWeight:'900',color:G},ayahListen:{height:36,paddingHorizontal:15,borderRadius:12,backgroundColor:'#E8F5EC',alignItems:'center',justifyContent:'center'},ayahListenOn:{backgroundColor:G},ayahListenText:{fontSize:10,fontWeight:'800',color:G},ayahListenTextOn:{color:'#FFF'},ayahArabic:{marginTop:13,fontSize:25,lineHeight:45,textAlign:'right',color:INK},pronunciation:{marginTop:10,fontSize:12,lineHeight:20,fontStyle:'italic',color:'#687A70'},translation:{marginTop:9,paddingTop:10,borderTopWidth:1,borderTopColor:'#E8EEE9',fontSize:13,lineHeight:21,color:'#334C40'}});
'@
Set-Content -LiteralPath $target -Value $source -Encoding utf8
